SELECT t.id, t.postId, t.userId, t.content, t.parentId, t.rootId, t.replyUserId, t.likeCount, t.createTime, t.authorNickname, t.authorAvatar, t.replyUserNickname FROM ( SELECT c.id, c.post_id AS postId, c.user_id AS userId, c.content, c.parent_id AS parentId, c.root_id AS rootId, c.reply_user_id AS replyUserId, c.like_count AS likeCount, c.create_time AS createTime, u.nickname AS authorNickname, u.avatar AS authorAvatar, ru.nickname AS replyUserNickname, ROW_NUMBER() OVER ( PARTITION BY c.root_id ORDER BY c.create_time ASC, c.id ASC ) AS rn FROM comment c LEFT JOIN `user` u ON u.id = c.user_id LEFT JOIN `user` ru ON ru.id = c.reply_user_id WHERE c.post_id = #{postId} AND c.deleted = 0 AND c.root_id IN
#{rootId}
) t WHERE t.rn <= 2 ORDER BY t.rootId ASC, t.createTime ASC

SELECT COUNT(*)
FROM comment
WHERE post_id = #{postId}
  AND root_id = #{rootId}
  AND deleted = 0

